16: function walkMemTitles(dir) {
17:   const titles = new Set();
18:   if (!fs.existsSync(dir)) return titles;
19:   for (const e of fs.readdirSync(dir, { withFileTypes: true })) {
20:     const p = path.join(dir, e.name);
21:     if (e.isDirectory()) walkMemTitles(p).forEach((t) => titles.add(t));
22:     else if (e.name.endsWith(".json")) {
23:       try {
24:         const j = JSON.parse(fs.readFileSync(p, "utf8"));
25:         for (const m of j.memories || []) if (m.title) titles.add(m.title);
26:       } catch {}
27:     }
28:   }
29:   return titles;
30: }
