40:   const proj = j.project || f;
41:   const batches = j.batches || [];
42:   if (!batches.length) continue;
43:   let ok = 0,
44:     failedZero = 0,
45:     timeout = 0,
46:     otherErr = 0;
47:   const riskyTitles = [];
48:   for (const b of batches) {
49:     if (b.error === "commit timeout") {
50:       timeout++;
51:       riskyTitles.push(...(b.titles || []));
52:       continue;
53:     }
54:     const st = b.result?.status;
55:     const ex = b.result?.extracted || {};
56:     if (st === "completed" && ((ex.memory_write || 0) > 0 || (ex.memory_edit || 0) > 0)) ok++;
57:     else if (st === "failed" || (st === "completed" && !ex.memory_write && !ex.memory_edit)) {
58:       failedZero++;
59:       riskyTitles.push(...(b.titles || []));
60:     } else if (b.error) otherErr++;
61:   }
62:   if (failedZero || timeout || otherErr)
63:     batchAudit.push({ project: proj, batches: batches.length, ok, failedZero, timeout, otherErr, riskyTitleCount: riskyTitles.length });
64: }
